import{_ as t,o as i,c as o,ah as a}from"./chunks/framework.DDXs_i7t.js";const p=JSON.parse('{"title":"Technical Vision: The Acoustics of the Mystery","description":"How we bring the voices of Diehl, Minichmayr, and Masucci to life using state-of-the-art AI.","frontmatter":{"title":"Technical Vision: The Acoustics of the Mystery","description":"How we bring the voices of Diehl, Minichmayr, and Masucci to life using state-of-the-art AI.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-02-27-technische-vision-audio.md","filePath":"en/logbuch/2026-02-27-technische-vision-audio.md"}'),n={name:"en/logbuch/2026-02-27-technische-vision-audio.md"};function s(r,e,h,c,l,u){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="technical-vision-the-acoustics-of-the-mystery" tabindex="-1">Technical Vision: The Acoustics of the Mystery <a class="header-anchor" href="#technical-vision-the-acoustics-of-the-mystery" aria-label="Permalink to &quot;Technical Vision: The Acoustics of the Mystery&quot;">​</a></h1><p>To transform the texts of our audiobook showcase into real audio experiences, we rely on a highly specialized workflow. A mockumentary thrives on atmosphere – mere reading of text is not enough.</p><h2 id="the-audio-setup" tabindex="-1">The Audio Setup <a class="header-anchor" href="#the-audio-setup" aria-label="Permalink to &quot;The Audio Setup&quot;">​</a></h2><h3 id="_1-voice-engineering-the-characters" tabindex="-1">1. Voice Engineering (The Characters) <a class="header-anchor" href="#_1-voice-engineering-the-characters" aria-label="Permalink to &quot;1. Voice Engineering (The Characters)&quot;">​</a></h3><p>We use <strong>ElevenLabs Studio 3.0</strong> as our central production platform.</p><ul><li><strong>Professional Voice Cloning (PVC):</strong> The voices of Birgit Minichmayr and August Diehl require the highest emotional variance. Through PVC, we can ensure that Heidi&#39;s arrogance and August W.&#39;s hectic pace sound authentic.</li><li><strong>Model Choice:</strong> For the dialogues, we use the <strong>V3 (Expressive)</strong> model, which responds best to subtle emotional nuances.</li></ul><h3 id="_2-sound-design-the-atmosphere" tabindex="-1">2. Sound Design (The Atmosphere) <a class="header-anchor" href="#_2-sound-design-the-atmosphere" aria-label="Permalink to &quot;2. Sound Design (The Atmosphere)&quot;">​</a></h3><p>An audiobook about the Horten fortune must smell like money – or at least sound like it.</p><ul><li><strong>Layering:</strong> In the studio timeline, we place subtle atmospheric sounds under the voices. The gentle splashing of Lake Wörthersee for Heidi, the hard clicking of a 1930s typewriter for Helmut, and nervous smartphone vibrations for the scenes in Linz.</li><li><strong>AI Interference:</strong> The voices of Grok and Gemini receive a slightly synthetic but high-resolution &quot;digital glow&quot; to emphasize their role as observers from the ether.</li></ul><h3 id="_3-speech-to-speech-the-direction" tabindex="-1">3. Speech-to-Speech (The Direction) <a class="header-anchor" href="#_3-speech-to-speech-the-direction" aria-label="Permalink to &quot;3. Speech-to-Speech (The Direction)&quot;">​</a></h3><p>If the AI does not immediately hit a certain emphasis (e.g., a particularly sarcastic peak), we use <strong>Speech-to-Speech</strong>. In this process, I (or Volti) speak the line with the desired intonation, and the AI adopts this dynamics one-to-one into the target voice.</p><h2 id="the-goal" tabindex="-1">The Goal <a class="header-anchor" href="#the-goal" aria-label="Permalink to &quot;The Goal&quot;">​</a></h2><p>The result will be an immersive audio play that acoustically blurs the boundaries between documentation and fiction. An archive of silence that you can hear.</p><p><em>Documented by Gemini CLI. February 2026.</em></p>',14)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
